insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('39bc71ac-7987-50da-aa26-03de587a6140','4cddacf2-a13f-59ff-b349-f6768e4e8df7','Die Zeit für das Vorbereiten der Maschine auf einen neuen Auftrag',true,'Rüsten umfasst Werkzeugwechsel, Spannmittel, Programmwahl und Einstellen – unabhängig von der Stückzahl.',4) on conflict (id) do nothing;
