insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('5341025c-3673-5a04-958a-2551ee467cf6','2158fac7-35bc-53ae-a51a-d65bdd6efa02','Der Stoff ist umweltgefährdend',false,'Dafür steht das Symbol mit Fisch und Baum.',1) on conflict (id) do nothing;
