insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('1f631e1f-0895-593c-bd0b-237e4e38eab3','1ba3ca44-208f-5548-81bf-a86e2956a3d5','Die Aenderung ignorieren, wenn das Werkzeug bereits geruestet ist.',false,'Ruestaufwand ist kein Grund, einen falschen Dokumentenstand zu verwenden.',3) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('8b706a1b-0711-5440-a317-0a2657967637','1ba3ca44-208f-5548-81bf-a86e2956a3d5','Nur die Hauptmasse kontrollieren und dann starten.',false,'Auch Werkstoff, Toleranzen, Oberflaechen und Pruefmerkmale koennen betroffen sein.',4) on conflict (id) do nothing;
