insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('c012dc01-4ce5-5852-9d35-19695a573eee','f75f7882-3fab-5dae-ba73-ccc8b20d81f7','Weil Werkstoff, Werkzeugwahl, Bearbeitungsdaten und Pruefanforderungen zusammenhaengen.',true,'Ein falscher Werkstoff kann zu Ausschuss, Werkzeugschaden oder Sicherheitsrisiken fuehren.',1) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('2df640b4-9ecb-5e3c-a6cd-34e0d97aa345','f75f7882-3fab-5dae-ba73-ccc8b20d81f7','Weil die Werkstoffnummer nur fuer die Lagerhaltung wichtig ist.',false,'Die Kennzeichnung ist auch fuer Fertigung, Pruefung und Rueckverfolgbarkeit wichtig.',2) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('2b6454cc-f8fb-515c-bf13-97e23300ed2b','f75f7882-3fab-5dae-ba73-ccc8b20d81f7','Weil alle Kunststoffe gleich bearbeitet werden koennen.',false,'Kunststoffe unterscheiden sich stark in Temperaturverhalten, Zaehigkeit und Bearbeitbarkeit.',3) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('64e47fa5-0530-545e-8ce4-b1dda78ac489','f75f7882-3fab-5dae-ba73-ccc8b20d81f7','Weil die Maschine den Werkstoff automatisch erkennt.',false,'Die Verantwortung fuer Materialbereitstellung und Kontrolle bleibt beim Prozess.',4) on conflict (id) do nothing;
