insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('50300261-6a57-5a36-80ea-bcc48b950e29','6aa109ca-a96b-5e3b-a775-78181aeeac1d','Sicherheitszustand pruefen, Meldungen lesen, Energieversorgung und Freigaben kontrollieren.',true,'Systematische Stoerungssuche beginnt sicher und dokumentiert, nicht mit blindem Verstellen.',1) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('1772837b-dcd4-56f0-9a4a-8ebee91a58af','6aa109ca-a96b-5e3b-a775-78181aeeac1d','Alle Parameter veraendern, bis die Anlage startet.',false,'Unkontrolliertes Verstellen erzeugt neue Fehler und gefaehrdet die Prozessfaehigkeit.',2) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('0b725b42-056c-51c6-9732-25663541e9d5','6aa109ca-a96b-5e3b-a775-78181aeeac1d','Schutzeinrichtungen ueberbruecken, um die Ursache schneller zu finden.',false,'Schutzeinrichtungen duerfen nicht umgangen werden.',3) on conflict (id) do nothing;
