insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('3d906686-38bc-5f5a-ada0-dd34f2306197','Zuerst wird die Anlage sicher angehalten und gegen gefaehrliche Bewegungen gesichert. Danach werden Stoermeldung, Zeitpunkt und betroffene Station dokumentiert. Anschliessend prueft man Werkstuecklage, Verschmutzung, Sensorabstand, Befestigung, Kabel und Signalzustand. Wenn die Ursache gefunden ist, wird sie beseitigt oder an Instandhaltung beziehungsweise Vorgesetzten gemeldet. Nach der Korrektur erfolgt ein sicherer Probelauf mit Funktionskontrolle und Dokumentation.','{"max_punkte": 5, "kriterien": [{"id": "k1", "beschreibung": "Sicheres Anhalten beziehungsweise Sichern der Anlage", "punkte": 1}, {"id": "k2", "beschreibung": "Stoermeldung und Zeitpunkt dokumentiert", "punkte": 1}, {"id": "k3", "beschreibung": "Sensorumfeld systematisch geprueft", "punkte": 1}, {"id": "k4", "beschreibung": "Meldung oder Beseitigung der Ursache beschrieben", "punkte": 1}, {"id": "k5", "beschreibung": "Probelauf und Dokumentation genannt", "punkte": 1}], "akzeptierte_synonyme": ["Lichtschranke", "Naeherschalter", "Signal pruefen", "Instandhaltung informieren"], "haeufige_fehler": ["Schutzeinrichtung ueberbruecken", "Parameter blind veraendern"]}'::jsonb,5) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('bff66bb8-f28b-504c-9511-00ee11e80938','48e4275e-0308-5f66-b4ef-c25c1c96dd28','freitext','Beschreiben Sie die wichtigsten Schritte, um einen Produktwechsel an einer Produktionsanlage vorzubereiten.',2,'entwurf',true,false,2,null,false,'AP-PP-AS-F03') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('bff66bb8-f28b-504c-9511-00ee11e80938','Zuerst werden Auftrag, Zeichnung, Arbeitsplan, Pruefplan und aktueller Stand geprueft. Danach werden Material, Werkzeuge, Spannmittel, Hilfsstoffe und Pruefmittel bereitgestellt. Die Anlage wird sicher stillgesetzt, gereinigt und nach Vorgabe umgeruestet. Prozessdaten oder Programme werden geladen und kontrolliert. Anschliessend erfolgt ein Probelauf beziehungsweise Erstteil mit Pruefung und Freigabe. Offene Punkte und Einstellungen werden dokumentiert.','{"max_punkte": 5, "kriterien": [{"id": "k1", "beschreibung": "Unterlagen und aktuellen Stand pruefen", "punkte": 1}, {"id": "k2", "beschreibung": "Material, Werkzeuge, Hilfs- und Pruefmittel bereitstellen", "punkte": 1}, {"id": "k3", "beschreibung": "Sicheres Stillsetzen und Umruesten beschrieben", "punkte": 1}, {"id": "k4", "beschreibung": "Parameter/Programm und Probelauf beziehungsweise Erstteil genannt", "punkte": 1}, {"id": "k5", "beschreibung": "Freigabe und Dokumentation genannt", "punkte": 1}], "akzeptierte_synonyme": ["Ruestplan", "Erstmuster", "Werkzeugwechsel", "Pruefplan"], "haeufige_fehler": ["Serienstart ohne Freigabe", "Materialkennzeichnung nicht pruefen"]}'::jsonb,5) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('8581ff51-7062-5778-8fa3-3db1508282aa','770eeb84-d9de-5b36-878a-b69b9024625f','freitext','Bei einer Serienpruefung wird ein Mass ausserhalb der Toleranz festgestellt. Beschreiben Sie Ihr Vorgehen.',3,'entwurf',true,false,2,null,false,'AP-PP-QS-F03') on conflict (id) do nothing;
insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('8581ff51-7062-5778-8fa3-3db1508282aa','Zuerst wird der Messwert durch geeignete Wiederholmessung und Pruefmittelkontrolle abgesichert. Wenn die Abweichung bestaetigt ist, wird die Fertigung gestoppt oder korrigiert und die zustaendige Person informiert. Seit der letzten guten Pruefung gefertigte Teile werden eingegrenzt, gesperrt und nachgeprueft. Die Ursache wird gesucht, zum Beispiel Werkzeugverschleiss, falsche Einstellung, Material- oder Temperaturproblem. Nach Korrektur wird ein neues Teil geprueft und die Massnahme dokumentiert.','{"max_punkte": 5, "kriterien": [{"id": "k1", "beschreibung": "Messwert und Pruefmittel kontrolliert", "punkte": 1}, {"id": "k2", "beschreibung": "Fertigung stoppen/korrigieren und Verantwortliche informieren", "punkte": 1}, {"id": "k3", "beschreibung": "Betroffene Teile eingrenzen und sperren", "punkte": 1}, {"id": "k4", "beschreibung": "Ursachensuche beschrieben", "punkte": 1}, {"id": "k5", "beschreibung": "Nachkontrolle und Dokumentation genannt", "punkte": 1}], "akzeptierte_synonyme": ["Sperrlager", "Rueckverfolgbarkeit", "Erstteil nach Korrektur"], "haeufige_fehler": ["Abweichung verschweigen", "Weiterfertigen bis Schichtende"]}'::jsonb,5) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('3d8dae76-7051-587e-9e08-7b4aa4cdedf1','453a2695-29fe-5daa-98f7-3b99a86b3763','freitext','Erklaeren Sie den Unterschied zwischen Wartung, Inspektion und Instandsetzung an einem Beispiel aus der Produktion.',2,'entwurf',true,false,2,null,false,'AP-PP-IH-F03') on conflict (id) do nothing;
