insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('3d8dae76-7051-587e-9e08-7b4aa4cdedf1','Wartung soll den Abbau des Abnutzungsvorrats verzoegern, zum Beispiel Schmieren, Reinigen oder Nachstellen einer Fuehrung. Inspektion stellt den Ist-Zustand fest und beurteilt ihn, zum Beispiel Kontrolle von Spiel, Verschleiss oder Dichtheit. Instandsetzung stellt nach einem Fehler den Sollzustand wieder her, zum Beispiel Austausch eines defekten Sensors oder einer verschlissenen Dichtung. Die Massnahmen muessen geplant, sicher ausgefuehrt und dokumentiert werden.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Wartung zutreffend erklaert", "punkte": 1}, {"id": "k2", "beschreibung": "Inspektion zutreffend erklaert", "punkte": 1}, {"id": "k3", "beschreibung": "Instandsetzung zutreffend erklaert", "punkte": 1}, {"id": "k4", "beschreibung": "Passendes Produktionsbeispiel oder Dokumentation genannt", "punkte": 1}], "akzeptierte_synonyme": ["Zustand feststellen", "Sollzustand wiederherstellen", "Schmieren"], "haeufige_fehler": ["Wartung und Inspektion verwechseln"]}'::jsonb,4) on conflict (frage_id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('c378ea25-eeb4-53bb-978e-0f89858d6a3a','3502eec5-14fa-54ec-9a78-335a5f03cb6f','freitext','Nennen Sie vier Gruende, warum der Ausbildungsnachweis sorgfaeltig gefuehrt werden muss.',2,'entwurf',true,false,2,null,false,'AP-WISO-BA-F03') on conflict (id) do nothing;
