insert into freitext_loesungen (frage_id,musterloesung,bewertungsraster,max_punkte) values ('c378ea25-eeb4-53bb-978e-0f89858d6a3a','Der Ausbildungsnachweis dokumentiert, welche Taetigkeiten und Lerninhalte vermittelt wurden. Er hilft Auszubildenden und Ausbildenden, Luecken im Ausbildungsplan zu erkennen. Er dient als Nachweis gegenueber Betrieb und zustaendiger Stelle und ist fuer die Pruefungszulassung relevant. Ausserdem unterstuetzt er die Reflexion der eigenen Arbeit und macht Fortschritte nachvollziehbar.','{"max_punkte": 4, "kriterien": [{"id": "k1", "beschreibung": "Dokumentation der Ausbildung genannt", "punkte": 1}, {"id": "k2", "beschreibung": "Erkennen von Luecken im Ausbildungsplan genannt", "punkte": 1}, {"id": "k3", "beschreibung": "Nachweis gegenueber zustaendiger Stelle oder Pruefungszulassung genannt", "punkte": 1}, {"id": "k4", "beschreibung": "Reflexion/Fortschritt oder Kommunikation mit Ausbilder genannt", "punkte": 1}], "akzeptierte_synonyme": ["Berichtsheft", "Ausbildungsplan", "Zulassung"], "haeufige_fehler": ["Ausbildungsnachweis als freiwillige Notiz darstellen"]}'::jsonb,4) on conflict (frage_id) do nothing;
