insert into content_elemente (id,traeger_id,titel,beschreibung,content_typ,pruefungsbereich_id,thema_id,unterthema_id,lerneinheit_id,frage_id,inhalt,schwierigkeitsgrad,status,ist_demo,demo_sichtbar,demo_label,fachlich_verifiziert,quellenart,ki_anbieter,ki_modell,ki_metadaten,qualitaetswert,qualitaetsmetadaten) values ('29a889fd-4685-533a-bed4-d6be9e92d3ed','4c89739f-2279-5917-9d6e-bc98fed1ffed','Spritzgiessen - ausfuehrliche Erklaerung','KI-generierter Beispielinhalt - nicht fachlich verifiziert','erklaerung','e851a2e5-aa36-5b69-8cb0-9b6e8f62908d','8f60c694-54b5-5f08-9138-11ae90ec0ed3','9579ebf8-b7b9-509d-b17f-2ee2fcc7dd0c','7e4f5eb3-ce9b-5d1b-b9b2-891207e30f43',null,'{"mdx": "## Spritzgiessen\n\nSpritzgiessen ist fuer Maschinen- und Anlagenfuehrer/-innen wichtig, weil es beim einrichten, bedienen und ueberwachen von fertigungsprozessen immer wieder vorkommt. Entscheidend ist nicht, Definitionen auswendig zu lernen, sondern den Zusammenhang zur Arbeit an Maschine, Werkzeug, Werkstoff und Pruefung zu verstehen.\n\nIn der Praxis pruefst du zuerst die Unterlagen, dann den Zustand von Material, Werkzeug, Maschine und Sicherheitseinrichtungen. Bei Spritzgiessen geht es meist um eine einfache Frage: Welche Eigenschaft, Einstellung oder Gefahr ist fuer den naechsten Arbeitsschritt entscheidend? Wenn Zahlenwerte, Grenzwerte oder Normangaben noetig sind, werden sie im Tabellenbuch, in der Zeichnung oder in der Betriebsanweisung nachgeschlagen.\n\nTypische Fehler sind vorschnelles Schaetzen, das Uebertragen von Werten auf andere Werkstoffe oder Maschinen und das Uebergehen von Warnhinweisen. Dieser Abschnitt ist als KI-generierter Beispielinhalt markiert und vor einem produktiven Einsatz fachlich zu pruefen.", "lesedauer_minuten": 7}'::jsonb,'schwer','generiert',true,true,'KI-generierter Beispielinhalt - nicht fachlich verifiziert',false,'demo','mock','seed-demo-content-v1','{"seed": "MAF_DemoContent", "modus": "mock", "deterministisch": true}'::jsonb,0.72,'{"hinweis": "Automatisch erzeugter Demo-Seed; vor Produktion fachlich pruefen.", "fachlich_verifiziert": false, "keine_original_pruefungsaufgabe": true}'::jsonb) on conflict (id) do nothing;
