insert into content_elemente (id,traeger_id,titel,beschreibung,content_typ,pruefungsbereich_id,thema_id,unterthema_id,lerneinheit_id,frage_id,inhalt,schwierigkeitsgrad,status,ist_demo,demo_sichtbar,demo_label,fachlich_verifiziert,quellenart,ki_anbieter,ki_modell,ki_metadaten,qualitaetswert,qualitaetsmetadaten) values ('df118f03-c34a-5b0f-8eb7-c8689382d371','4c89739f-2279-5917-9d6e-bc98fed1ffed','Schnitte - ausfuehrliche Erklaerung','KI-generierter Beispielinhalt - nicht fachlich verifiziert','erklaerung','e851a2e5-aa36-5b69-8cb0-9b6e8f62908d','26f105c7-cc7d-50f5-a6b4-ce9d06160d27','7f9283bf-f62e-5308-8660-711b9da657d2','7dbd8e63-c880-584a-9122-6c508d8c17f0',null,'{"mdx": "## Schnitte\n\nSchnitte ist fuer Maschinen- und Anlagenfuehrer/-innen wichtig, weil es beim lesen und umsetzen technischer unterlagen immer wieder vorkommt. Entscheidend ist nicht, Definitionen auswendig zu lernen, sondern den Zusammenhang zur Arbeit an Maschine, Werkzeug, Werkstoff und Pruefung zu verstehen.\n\nIn der Praxis pruefst du zuerst die Unterlagen, dann den Zustand von Material, Werkzeug, Maschine und Sicherheitseinrichtungen. Bei Schnitte geht es meist um eine einfache Frage: Welche Eigenschaft, Einstellung oder Gefahr ist fuer den naechsten Arbeitsschritt entscheidend? Wenn Zahlenwerte, Grenzwerte oder Normangaben noetig sind, werden sie im Tabellenbuch, in der Zeichnung oder in der Betriebsanweisung nachgeschlagen.\n\nTypische Fehler sind vorschnelles Schaetzen, das Uebertragen von Werten auf andere Werkstoffe oder Maschinen und das Uebergehen von Warnhinweisen. Dieser Abschnitt ist als KI-generierter Beispielinhalt markiert und vor einem produktiven Einsatz fachlich zu pruefen.", "lesedauer_minuten": 7}'::jsonb,'schwer','generiert',true,true,'KI-generierter Beispielinhalt - nicht fachlich verifiziert',false,'demo','mock','seed-demo-content-v1','{"seed": "MAF_DemoContent", "modus": "mock", "deterministisch": true}'::jsonb,0.72,'{"hinweis": "Automatisch erzeugter Demo-Seed; vor Produktion fachlich pruefen.", "fachlich_verifiziert": false, "keine_original_pruefungsaufgabe": true}'::jsonb) on conflict (id) do nothing;
